style.css:
/* Styl ogólny */
@media (max-width: 768px) { /* Tablet */
  body {
    background-color: #121212;
    font-family: 'My Hero Academia', sans-serif;
    background-image: url('https://your-link-to-UA-background.jpg');
    background-size: cover;
    background-position: center center;
    background-attachment: fixed;
    animation: moveBackground 20s infinite linear;
  }

  @keyframes moveBackground {
    0% { background-position: 0 0; }
    100% { background-position: 100% 100%; }
  }

  /* Ekran ładowania z chibi postaciami LOV */
  .loading-screen {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background-color: rgba(0, 0, 0, 0.9);
    display: flex;
    justify-content: center;
    align-items: center;
  }

  /* Zmniejszenie rozmiaru postaci na mniejszych ekranach */
  .loading-screen img {
    width: 50px; /* Dostosowanie rozmiaru postaci */
    margin: 10px;
    position: absolute;
    animation: chibiRun 4s infinite linear;
  }

  /* Animacja poruszających się postaci */
  @keyframes chibiRun {
    0% { transform: translateX(-100px) scale(1); }
    25% { transform: translateX(100px) scale(1.1); }
    50% { transform: translateX(200px) scale(1); }
    75% { transform: translateX(300px) scale(1.1); }
    100% { transform: translateX(400px) scale(1); }
  }

  /* Logo YouTube */
  #logo img {
    width: 100px; /* Zmniejszenie rozmiaru logo */
    filter: sepia(1) hue-rotate(90deg) saturate(1.5);
  }

  /* Nagłówek */
  #masthead {
    background: rgba(0, 0, 0, 0.6);
    height: 50px;
    padding: 0 10px;
    display: flex;
    align-items: center;
    border-bottom: 3px solid #FFD700;
  }

  /* Czcionka w nagłówku */
  #masthead a {
    color: #FFD700;
    font-family: 'My Hero Academia', sans-serif;
    font-weight: bold;
    text-shadow: 2px 2px 5px rgba(0, 0, 0, 0.8);
  }

  /* Styl przycisków subskrypcji i lajków */
  ytd-subscribe-button-renderer, ytd-toggle-button-renderer.style-scope.ytd-menu-renderer {
    padding: 5px 10px;
    font-size: 14px;
  }

  /* Wyszukiwanie na małych ekranach */
  ytd-searchbox #search {
    background-color: #1a1a1a;
    color: #fff;
    border-radius: 25px;
    border: 1px solid #00bcd4;
    padding: 5px 10px;
    font-size: 14px;
  }

  /* Zmniejszenie miniaturki wideo */
  .ytd-video-renderer {
    padding: 5px;
    margin: 5px 0;
  }

  /* Zmiana widoczności dla sekcji */
  ytd-section-list-renderer {
    border-top: 2px solid #FFD700;
    padding-top: 10px;
  }

  /* Poprawienie wyglądu playlist */
  ytd-playlist-video-list-renderer {
    background-color: #f06292;
    padding: 10px;
    color: #FFF;
  }

  /* Zmiana kolorów na mniejszych ekranach */
  .ytp-chrome-top {
    background: rgba(0, 0, 0, 0.9);
  }
}

/* Styl dla telefonów komórkowych (mniejsze ekrany) */
@media (max-width: 480px) {
  body {
    font-size: 14px; /* Dostosowanie czcionki na telefonach */
  }

  /* Zmniejszenie rozmiaru miniaturki na małych ekranach */
  .loading-screen img {
    width: 40px;
  }

  /* Logo YouTube */
  #logo img {
    width: 80px;
  }

  /* Nagłówek */
  #masthead {
    height: 45px; /* Zmniejszenie nagłówka */
    padding: 0 8px;
  }

  /* Czcionka w nagłówku */
  #masthead a {
    font-size: 12px;
  }

  /* Przyciski subskrypcji */
  ytd-subscribe-button-renderer {
    padding: 5px 8px;
    font-size: 12px;
  }

  /* Wyszukiwanie */
  ytd-searchbox #search {
    padding: 4px 8px;
    font-size: 13px;
  }

  /* Zmniejszenie przycisków wideo i sekcji */
  .ytd-video-renderer {
    padding: 5px;
    margin: 5px 0;
  }

  /* Zmniejszenie wielkości playlisty */
  ytd-playlist-video-list-renderer {
    font-size: 12px;
  }
}
